-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_histology_clean
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_histology_clean AS WITH base AS (SELECT e.*, lower(main."trim"(regexp_replace(COALESCE(e.primary_histology, ''), '\s+', ' ', 'g'))) AS _hist_trim FROM main.canonical_path_malignant_events_v1 AS e), stripped AS (SELECT b.*, main."trim"(regexp_replace(_hist_trim, '^(metastatic/recurrent|recurrent/metastatic|metastatic|recurrent)\s+', '', 'g')) AS _hist_met_stripped FROM base AS b)SELECT s.* EXCLUDE (_hist_met_stripped, _hist_trim), s.primary_histology AS primary_histology_raw, CASE  WHEN (((s._hist_trim = '') OR (s._hist_trim IS NULL))) THEN (NULL) WHEN (((s._hist_met_stripped = 'ptc') OR (s._hist_met_stripped ~~ 'ptc %') OR (s._hist_met_stripped ~~ 'ptc/%') OR (s._hist_met_stripped ~~ 'high-grade ptc%') OR (s._hist_met_stripped ~~ '%ptc tall%') OR (s._hist_met_stripped ~~ '%ptc classical%') OR (s._hist_met_stripped ~~ '%ptc classic%') OR (s._hist_met_stripped ~~ '%ptc follicular%') OR (s._hist_met_stripped ~~ '%ptc with %') OR (s._hist_met_stripped ~~ '%ptc?%') OR (s._hist_met_stripped ~~ '%ptc high grade%') OR (s._hist_met_stripped ~~ '%ptc microcarcinoma%') OR (s._hist_met_stripped ~~ '%ptc nos%') OR (s._hist_met_stripped ~~ '%ptc onocytic%') OR (s._hist_met_stripped ~~ '%ptc calssical%') OR (s._hist_met_stripped ~~ '*ptc%') OR (s._hist_met_stripped ~~ 'metastatitic ptc%') OR (s._hist_met_stripped ~~ 'poorly differentied ptc%') OR ((s._hist_met_stripped ~~ '%papillary%') AND (s._hist_met_stripped ~~ '%carcinoma%')) OR (s._hist_met_stripped ~~ '%paillary%') OR (s._hist_met_stripped ~~ '**thyroid biopsy%ptc%'))) THEN ('papillary thyroid carcinoma') WHEN (((s._hist_met_stripped = 'mtc') OR (s._hist_met_stripped ~~ 'mtc %') OR (s._hist_met_stripped ~~ 'mtc/%') OR (s._hist_met_stripped = 'medullary') OR ((s._hist_met_stripped ~~ '%medullary%') AND (s._hist_met_stripped ~~ '%carcinoma%')))) THEN ('medullary thyroid carcinoma') WHEN (((s._hist_met_stripped ~~ '%anaplastic%') OR (s._hist_met_stripped ~~ '**thyroid biopsy%anaplastic%'))) THEN ('anaplastic thyroid carcinoma') WHEN (((s._hist_met_stripped ~~ '%hurthle cell carcinoma%') OR ((s._hist_met_stripped ~~ '%hurthle%') AND (s._hist_met_stripped ~~ '%carcinoma%')) OR (s._hist_met_stripped ~~ '%oncocytic%carcinoma%'))) THEN ('oncocytic thyroid carcinoma') WHEN (((s._hist_met_stripped = 'niftp') OR (s._hist_met_stripped ~~ '%(niftp)%') OR (s._hist_met_stripped ~~ '%niftp%'))) THEN ('NIFTP') WHEN (((s._hist_met_stripped = 'ftump') OR (s._hist_met_stripped ~~ '%ft-ump%') OR (s._hist_met_stripped ~~ '%ftump%'))) THEN ('FTUMP') WHEN (((s._hist_met_stripped ~~ '%atypical follicular%') OR (s._hist_met_stripped ~~ '%atypical hurthle cell neoplasm%'))) THEN ('atypical follicular / hurthle neoplasm') WHEN ((s._hist_met_stripped ~~ '%follicular adenoma%')) THEN ('follicular adenoma') WHEN (((s._hist_met_stripped ~~ '%uncertain malignant potential%') OR (s._hist_met_stripped ~~ '%lesion of uncertain%'))) THEN ('uncertain malignant potential (non-FTUMP)') WHEN (((s._hist_met_stripped ~~ '%follicular%') AND ((s._hist_met_stripped ~~ '%carcinoma%') OR (s._hist_met_stripped ~~ '%caricinoma%')))) THEN ('follicular thyroid carcinoma') WHEN ((s._hist_met_stripped ~~ '%differentiated high grade%')) THEN ('differentiated high grade thyroid carcinoma') WHEN (((s._hist_met_stripped ~~ '%poorly differentiated%') OR (s._hist_met_stripped ~~ '%pooly differentiated%') OR (s._hist_met_stripped ~~ '%poorly differentied%'))) THEN ('poorly differentiated thyroid carcinoma') WHEN ((s._hist_met_stripped ~~ '%neuroendocrine%')) THEN ('poorly differentiated neuroendocrine carcinoma') WHEN ((s._hist_met_stripped ~~ '%insular carcinoma%')) THEN ('insular carcinoma') WHEN ((s._hist_met_stripped ~~ '%differentiated thyroid carcinoma%')) THEN ('differentiated thyroid carcinoma') WHEN ((s._hist_met_stripped ~~ '%angiosarcoma%')) THEN ('angiosarcoma') WHEN ((s._hist_met_stripped ~~ '%adenoid cystic%')) THEN ('adenoid cystic carcinoma') WHEN ((s._hist_met_stripped ~~ '%nut carcinoma%')) THEN ('NUT carcinoma') WHEN (((s._hist_met_stripped ~~ '%thymic%') OR (s._hist_met_stripped ~~ '%thymus like%') OR (s._hist_met_stripped ~~ '%thymus-like%'))) THEN ('thymic-like carcinoma') WHEN (((s._hist_met_stripped ~~ '%squamous%') OR (s._hist_met_stripped ~~ '%high grade%carcinoma%'))) THEN ('high grade / squamous thyroid carcinoma') WHEN (((s._hist_met_stripped ~~ '%thyroid carcinoma%') OR (s._hist_met_stripped ~~ '%carcinoma%'))) THEN ('thyroid carcinoma unspecified') ELSE s._hist_met_stripped END AS primary_histology_clean, (s._hist_trim ~~ 'metastatic %') AS histology_metastatic_flag, ((s._hist_trim ~~ 'recurrent %') OR (s._hist_trim ~~ 'recurrent/%')) AS histology_recurrent_flag FROM stripped AS s;
